// Recebe a saida de "Buscar Grupos" e emite 1 item por grupo.
// Defensivo: a resposta pode vir como array de grupos, {groups:[...]}, ou 1 item/grupo.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const groups = Array.isArray(j) ? j : (Array.isArray(j.groups) ? j.groups : [j]);
  for (const g of groups) {
    const jid = g.id || g.remoteJid || g.jid;
    if (!jid || !String(jid).endsWith("@g.us")) continue;
    out.push({
      json: {
        group_jid: jid,
        name: g.subject || g.subjectOwner || g.name || null,
        instance: g.instanceId || "SUA_INSTANCIA",
      },
    });
  }
}
return out;

// Achata as mensagens de todos os grupos e mapeia p/ linhas de whatsapp_group_messages.
// LOOKBACK_HORAS: use 24 no dia a dia. No PRIMEIRO backfill, use um numero grande
// (ex.: 24 * 365) ou 0 para desligar o filtro e pegar todo o historico disponivel.
const LOOKBACK_HORAS = 24;
const cutoffMs = LOOKBACK_HORAS > 0 ? Date.now() - LOOKBACK_HORAS * 3600 * 1000 : 0;

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  // find-messages (Evolution v2) costuma devolver { messages: { records: [...] } }
  const records =
    (j.messages && Array.isArray(j.messages.records) && j.messages.records) ||
    (Array.isArray(j.messages) && j.messages) ||
    (Array.isArray(j) && j) ||
    [];

  for (const r of records) {
    const key = r.key || {};
    if (!key.id) continue;

    const groupJid = key.remoteJid || "";
    if (!groupJid.endsWith("@g.us")) continue; // so grupos

    let ts = r.messageTimestamp ?? null;
    const tsMs =
      typeof ts === "number"
        ? (ts < 1e12 ? ts * 1000 : ts)
        : ts
        ? new Date(ts).getTime()
        : Date.now();
    if (tsMs < cutoffMs) continue;

    out.push({
      json: {
        clinic_id: null, // mapeado depois via whatsapp_groups (grupo -> clinica)
        instance: r.instanceId || "SUA_INSTANCIA",
        group_jid: groupJid,
        message_id: key.id,
        from_me: key.fromMe === true, // true = conta do bot (a instancia)
        participant: key.participant ? String(key.participant).split("@")[0] : null,
        push_name: r.pushName || null,
        message_type: r.messageType || null,
        event_ts: new Date(tsMs).toISOString(),
      },
    });
  }
}
return out;
